// Manually implemented — not generated by codegen.
// CZ_PARTY_MESSAGE / 0x0108 has no C struct; it is variable-length and parsed
// manually in clif.cpp via clif_process_message with whisperFormat=false.

package send

// PartyChat is the request struct for the party_chat action.
// Name is the sender's character name; Message is the text to send.
// The wire format encodes "Name : Message\0" identical to PublicChat.
type PartyChat struct {
	Name    string
	Message string
}
